    h=open(p).read()
    for m in re.findall(r'(?:src|href)="(/(?:_images|includes/panels)[^"]+)"', h):
        imgs.add(m)
for i in sorted(imgs):
    fn=i.strip('/').replace('/','_')
    try:
        urllib.request.urlretrieve(base+i, fn)
        print('OK',fn, os.path.getsize(fn) if False else '')
